  const es = ema(close, cfg.emaSlow);
  const candles = new Array(n);
  for (let k = 0; k < n; k++) {
    candles[k] = { time: 0, open: open[k], high: high[k], low: low[k], close: close[k], volume: 0 };
  }
  const atrArr = atr(candles, cfg.atrPeriod);
